<template><div class="admin-form-page"><header class="admin-page-header"><div><h1>消息发布</h1><p>向平台用户发布广播消息。</p></div></header><el-form ref="form" :model="form" :rules="rules" label-position="top" @submit.native.prevent="publish"><el-form-item label="主题" prop="subject"><el-input v-model.trim="form.subject" maxlength="200" show-word-limit/></el-form-item><el-form-item label="正文" prop="body"><el-input v-model="form.body" type="textarea" :rows="8"/></el-form-item><p v-if="error" class="admin-error" role="alert">{{error}}</p><p v-if="success" class="admin-success" role="status">{{success}}</p><el-button class="publish-button" type="primary" :loading="submitting" @click="publish"><Send :size="17"/>发布消息</el-button></el-form></div></template>
<script>import{Send}from'lucide-vue';import{adminApi}from'../api/index.js';import{adminProblemMessage}from'../ui/admin-model.js';export default{name:'MessagesView',components:{Send},data:()=>({submitting:false,error:'',success:'',form:{subject:'',body:''},rules:{subject:[{required:true,message:'请输入主题',trigger:'blur'}],body:[{required:true,message:'请输入正文',trigger:'blur'}]}}),methods:{publish(){this.$refs.form.validate(async valid=>{if(!valid)return;this.submitting=true;this.error='';this.success='';try{const message=await adminApi.publishMessage({...this.form});this.success=`消息 #${message.id} 已发布。`;this.form={subject:'',body:''};}catch(problem){this.error=adminProblemMessage(problem);}finally{this.submitting=false;}});}}};</script>
